-- Generated by scripts/generate-transactional-admin-counts.mjs.

-- IPD-012: exact admin counts belong to source mutations, not repeated catalogue scans.

-- Preserve orphan asset totals, catalogue-only dashboard counts and all existing filters.

-- The one-time seed is cost-admitted; subsequent deltas touch only changed genes/assets.

INSERT OR REPLACE INTO icono_admin_dashboard_summary (summary_key, genes, with_live, overrides, drift, current_asset_missing, missing, no_live, stale_assets, legacy_assets, zero_candidates, one_candidate, two_to_five_candidates, six_plus_candidates, updated_at)
      SELECT 'default', COALESCE(SUM(1), 0),
        COALESCE(SUM((COALESCE(gr.current_asset_sha256, '') <> '')), 0),
        COALESCE(SUM((COALESCE(gr.admin_override, 0) = 1 AND COALESCE(gr.current_asset_sha256, '') <> '')), 0),
        COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0),
        COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0),
        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0),
        COALESCE(SUM((COALESCE(gr.current_asset_sha256, '') = '')), 0),
        COALESCE(SUM(COALESCE(gr.stale_count, 0)), 0),
        COALESCE(SUM(COALESCE(gr.legacy_count, 0)), 0),
        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0),
        COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 1)), 0),
        COALESCE(SUM((COALESCE(gr.candidate_count, 0) BETWEEN 2 AND 5)), 0),
        COALESCE(SUM((COALESCE(gr.candidate_count, 0) >= 6)), 0), CURRENT_TIMESTAMP
      FROM icono_gene_catalog gc LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = gc.gene_symbol;

WITH counts AS (
    SELECT COALESCE(SUM(1), 0) AS count_all,
      COALESCE(SUM((COALESCE(gr.current_asset_missing, 0) = 1)), 0) AS count_mismatch,
      COALESCE(SUM((COALESCE(gr.admin_override, 0) = 1)), 0) AS count_pinned,
      COALESCE(SUM((COALESCE(gr.candidate_count, 0) = 0)), 0) AS count_missing,
      COALESCE(SUM((COALESCE(gr.stale_count, 0) > 0)), 0) AS count_stale FROM icono_admin_gene_rollup gr
    ), filters(filter) AS (VALUES ('all'), ('mismatch'), ('pinned'), ('missing'), ('stale'))
    INSERT OR REPLACE INTO icono_admin_gallery_count_cache (count_key, mode, filter, total, updated_at)
    SELECT 'live:' || filter, 'live', filter, CASE filter WHEN 'all' THEN count_all WHEN 'mismatch' THEN count_mismatch WHEN 'pinned' THEN count_pinned WHEN 'missing' THEN count_missing WHEN 'stale' THEN count_stale END,
      CURRENT_TIMESTAMP FROM counts CROSS JOIN filters;

WITH counts AS (
    SELECT COALESCE(SUM(1), 0) AS count_all,
      COALESCE(SUM(COALESCE(gr.current_asset_missing, 0) = 1), 0) AS count_mismatch,
      COALESCE(SUM(COALESCE(gr.admin_override, 0) = 1), 0) AS count_pinned,
      COALESCE(SUM(0), 0) AS count_missing,
      COALESCE(SUM(COALESCE(pa.is_stale, 0) = 1), 0) AS count_stale FROM icono_portrait_assets pa LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = pa.gene_symbol WHERE pa.asset_sha256 <> ''
    ), filters(filter) AS (VALUES ('all'), ('mismatch'), ('pinned'), ('missing'), ('stale'))
    INSERT OR REPLACE INTO icono_admin_gallery_count_cache (count_key, mode, filter, total, updated_at)
    SELECT 'all:' || filter, 'all', filter, CASE filter WHEN 'all' THEN count_all WHEN 'mismatch' THEN count_mismatch WHEN 'pinned' THEN count_pinned WHEN 'missing' THEN count_missing WHEN 'stale' THEN count_stale END,
      CURRENT_TIMESTAMP FROM counts CROSS JOIN filters;

CREATE TRIGGER trg_icono_admin_counts_rollup_insert AFTER INSERT ON icono_admin_gene_rollup
BEGIN
  UPDATE icono_admin_dashboard_summary SET
    with_live = with_live + ((COALESCE(NEW.current_asset_sha256, '') <> '')) - (('' <> '')),
    overrides = overrides + ((COALESCE(NEW.admin_override, 0) = 1 AND COALESCE(NEW.current_asset_sha256, '') <> '')) - ((0 = 1 AND '' <> '')),
    drift = drift + ((COALESCE(NEW.current_asset_missing, 0) = 1)) - ((0 = 1)),
    current_asset_missing = current_asset_missing + ((COALESCE(NEW.current_asset_missing, 0) = 1)) - ((0 = 1)),
    missing = missing + ((COALESCE(NEW.candidate_count, 0) = 0)) - ((0 = 0)),
    no_live = no_live + ((COALESCE(NEW.current_asset_sha256, '') = '')) - (('' = '')),
    stale_assets = stale_assets + (COALESCE(NEW.stale_count, 0)) - (0),
    legacy_assets = legacy_assets + (COALESCE(NEW.legacy_count, 0)) - (0),
    zero_candidates = zero_candidates + ((COALESCE(NEW.candidate_count, 0) = 0)) - ((0 = 0)),
    one_candidate = one_candidate + ((COALESCE(NEW.candidate_count, 0) = 1)) - ((0 = 1)),
    two_to_five_candidates = two_to_five_candidates + ((COALESCE(NEW.candidate_count, 0) BETWEEN 2 AND 5)) - ((0 BETWEEN 2 AND 5)),
    six_plus_candidates = six_plus_candidates + ((COALESCE(NEW.candidate_count, 0) >= 6)) - ((0 >= 6)),
    updated_at = CURRENT_TIMESTAMP WHERE summary_key = 'default'
    AND EXISTS (SELECT 1 FROM icono_gene_catalog WHERE gene_symbol = NEW.gene_symbol);
  UPDATE icono_admin_gallery_count_cache SET total = total + (1 - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:all' AND (1 - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:mismatch' AND ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.admin_override, 0) = 1) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:pinned' AND ((COALESCE(NEW.admin_override, 0) = 1) - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.candidate_count, 0) = 0) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:missing' AND ((COALESCE(NEW.candidate_count, 0) = 0) - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + ((COALESCE(NEW.stale_count, 0) > 0) - 0), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'live:stale' AND ((COALESCE(NEW.stale_count, 0) > 0) - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) *
      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = NEW.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND ((COALESCE(NEW.current_asset_missing, 0) = 1) - 0) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (((COALESCE(NEW.admin_override, 0) = 1) - 0) *
      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = NEW.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND ((COALESCE(NEW.admin_override, 0) = 1) - 0) <> 0;
END;

