  UPDATE icono_admin_gallery_count_cache SET total = total + ((0 - (COALESCE(OLD.current_asset_missing, 0) = 1)) *
      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = OLD.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND (0 - (COALESCE(OLD.current_asset_missing, 0) = 1)) <> 0;
