      (SELECT COUNT(*) FROM icono_portrait_assets WHERE gene_symbol = OLD.gene_symbol AND asset_sha256 <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND (0 - (COALESCE(OLD.admin_override, 0) = 1)) <> 0;
