CREATE TRIGGER trg_icono_admin_counts_catalog_insert AFTER INSERT ON icono_gene_catalog
BEGIN
  UPDATE icono_admin_dashboard_summary SET (genes, with_live, overrides, drift, current_asset_missing, missing, no_live, stale_assets, legacy_assets, zero_candidates, one_candidate, two_to_five_candidates, six_plus_candidates) = (
    SELECT icono_admin_dashboard_summary.genes + (1),
      icono_admin_dashboard_summary.with_live + ((COALESCE(gr.current_asset_sha256, '') <> '')),
      icono_admin_dashboard_summary.overrides + ((COALESCE(gr.admin_override, 0) = 1 AND COALESCE(gr.current_asset_sha256, '') <> '')),
      icono_admin_dashboard_summary.drift + ((COALESCE(gr.current_asset_missing, 0) = 1)),
      icono_admin_dashboard_summary.current_asset_missing + ((COALESCE(gr.current_asset_missing, 0) = 1)),
      icono_admin_dashboard_summary.missing + ((COALESCE(gr.candidate_count, 0) = 0)),
      icono_admin_dashboard_summary.no_live + ((COALESCE(gr.current_asset_sha256, '') = '')),
      icono_admin_dashboard_summary.stale_assets + (COALESCE(gr.stale_count, 0)),
      icono_admin_dashboard_summary.legacy_assets + (COALESCE(gr.legacy_count, 0)),
      icono_admin_dashboard_summary.zero_candidates + ((COALESCE(gr.candidate_count, 0) = 0)),
      icono_admin_dashboard_summary.one_candidate + ((COALESCE(gr.candidate_count, 0) = 1)),
      icono_admin_dashboard_summary.two_to_five_candidates + ((COALESCE(gr.candidate_count, 0) BETWEEN 2 AND 5)),
      icono_admin_dashboard_summary.six_plus_candidates + ((COALESCE(gr.candidate_count, 0) >= 6))
    FROM (SELECT 1) singleton LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = NEW.gene_symbol
  ), updated_at = CURRENT_TIMESTAMP WHERE summary_key = 'default';
END;

CREATE TRIGGER trg_icono_admin_counts_catalog_delete AFTER DELETE ON icono_gene_catalog
BEGIN
  UPDATE icono_admin_dashboard_summary SET (genes, with_live, overrides, drift, current_asset_missing, missing, no_live, stale_assets, legacy_assets, zero_candidates, one_candidate, two_to_five_candidates, six_plus_candidates) = (
    SELECT icono_admin_dashboard_summary.genes - (1),
