    FROM (SELECT 1) singleton LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = OLD.gene_symbol
  ), updated_at = CURRENT_TIMESTAMP WHERE summary_key = 'default';
  UPDATE icono_admin_dashboard_summary SET (genes, with_live, overrides, drift, current_asset_missing, missing, no_live, stale_assets, legacy_assets, zero_candidates, one_candidate, two_to_five_candidates, six_plus_candidates) = (
    SELECT icono_admin_dashboard_summary.genes + (1),
      icono_admin_dashboard_summary.with_live + ((COALESCE(gr.current_asset_sha256, '') <> '')),
      icono_admin_dashboard_summary.overrides + ((COALESCE(gr.admin_override, 0) = 1 AND COALESCE(gr.current_asset_sha256, '') <> '')),
      icono_admin_dashboard_summary.drift + ((COALESCE(gr.current_asset_missing, 0) = 1)),
      icono_admin_dashboard_summary.current_asset_missing + ((COALESCE(gr.current_asset_missing, 0) = 1)),
      icono_admin_dashboard_summary.missing + ((COALESCE(gr.candidate_count, 0) = 0)),
      icono_admin_dashboard_summary.no_live + ((COALESCE(gr.current_asset_sha256, '') = '')),
      icono_admin_dashboard_summary.stale_assets + (COALESCE(gr.stale_count, 0)),
      icono_admin_dashboard_summary.legacy_assets + (COALESCE(gr.legacy_count, 0)),
      icono_admin_dashboard_summary.zero_candidates + ((COALESCE(gr.candidate_count, 0) = 0)),
      icono_admin_dashboard_summary.one_candidate + ((COALESCE(gr.candidate_count, 0) = 1)),
      icono_admin_dashboard_summary.two_to_five_candidates + ((COALESCE(gr.candidate_count, 0) BETWEEN 2 AND 5)),
      icono_admin_dashboard_summary.six_plus_candidates + ((COALESCE(gr.candidate_count, 0) >= 6))
    FROM (SELECT 1) singleton LEFT JOIN icono_admin_gene_rollup gr ON gr.gene_symbol = NEW.gene_symbol
  ), updated_at = CURRENT_TIMESTAMP WHERE summary_key = 'default';
END;

CREATE TRIGGER trg_icono_admin_counts_asset_insert AFTER INSERT ON icono_portrait_assets
BEGIN
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ (COALESCE(NEW.asset_sha256, '') <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:all' AND (+ (COALESCE(NEW.asset_sha256, '') <> '')) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND COALESCE(NEW.is_stale, 0) = 1)), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:stale' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND COALESCE(NEW.is_stale, 0) = 1)) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND current_asset_missing = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND current_asset_missing = 1))) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND admin_override = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND admin_override = 1))) <> 0;
END;

CREATE TRIGGER trg_icono_admin_counts_asset_delete AFTER DELETE ON icono_portrait_assets
BEGIN
  UPDATE icono_admin_gallery_count_cache SET total = total + (- (COALESCE(OLD.asset_sha256, '') <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:all' AND (- (COALESCE(OLD.asset_sha256, '') <> '')) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND COALESCE(OLD.is_stale, 0) = 1)), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:stale' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND COALESCE(OLD.is_stale, 0) = 1)) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND current_asset_missing = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND current_asset_missing = 1))) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND admin_override = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND admin_override = 1))) <> 0;
END;

CREATE TRIGGER trg_icono_admin_counts_asset_update AFTER UPDATE OF gene_symbol, asset_sha256, is_stale ON icono_portrait_assets
WHEN OLD.gene_symbol IS NOT NEW.gene_symbol OR OLD.asset_sha256 IS NOT NEW.asset_sha256 OR OLD.is_stale IS NOT NEW.is_stale
BEGIN
  UPDATE icono_admin_gallery_count_cache SET total = total + (- (COALESCE(OLD.asset_sha256, '') <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:all' AND (- (COALESCE(OLD.asset_sha256, '') <> '')) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND COALESCE(OLD.is_stale, 0) = 1)), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:stale' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND COALESCE(OLD.is_stale, 0) = 1)) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND current_asset_missing = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND current_asset_missing = 1))) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND admin_override = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND (- ((COALESCE(OLD.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = OLD.gene_symbol AND admin_override = 1))) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ (COALESCE(NEW.asset_sha256, '') <> '')), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:all' AND (+ (COALESCE(NEW.asset_sha256, '') <> '')) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND COALESCE(NEW.is_stale, 0) = 1)), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:stale' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND COALESCE(NEW.is_stale, 0) = 1)) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND current_asset_missing = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:mismatch' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND current_asset_missing = 1))) <> 0;
  UPDATE icono_admin_gallery_count_cache SET total = total + (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND admin_override = 1))), updated_at = CURRENT_TIMESTAMP WHERE count_key = 'all:pinned' AND (+ ((COALESCE(NEW.asset_sha256, '') <> '') AND EXISTS (
      SELECT 1 FROM icono_admin_gene_rollup WHERE gene_symbol = NEW.gene_symbol AND admin_override = 1))) <> 0;
END;
